"""textkit command line: `python3 -m textkit <command> ...`.

Every command is registered with @command. Library functions raise ValueError on bad input;
main() turns that into `error: <message>` on stderr and exit status 2.
"""
import argparse
import contextlib
import csv
import io
import json
import re
import sys

from . import core, duration, mdtable

COMMANDS = {}


def command(name, help, args=()):
    """Register a subcommand. args is a list of (name_or_flag, add_argument kwargs) pairs."""
    def deco(fn):
        COMMANDS[name] = {"help": help, "args": args, "run": fn}
        return fn
    return deco


@command("shout", "upper-case the text", [("text", {})])
def _shout(a):
    print(core.shout(a.text))
    return 0


@command("count", "count the words in the text", [("text", {})])
def _count(a):
    print(core.count_words(a.text))
    return 0


@command("dur", "convert between seconds and durations like 1h30m", [("value", {})])
def _dur(a):
    if re.fullmatch(r"[0-9]+", a.value):
        print(duration.format_duration(int(a.value)))
    else:
        print(duration.parse_duration(a.value))
    return 0


@command("mdtable", "read CSV from stdin and print a markdown table")
def _mdtable(a):
    print(mdtable.to_markdown(list(csv.reader(sys.stdin))))
    return 0


@command("commands", "list every command")
def _commands(a):
    for name in sorted(COMMANDS):
        print(name)
    return 0


def main(argv=None):
    p = argparse.ArgumentParser(prog="textkit")
    p.add_argument("--json", action="store_true", help="print the result as one JSON object")
    sub = p.add_subparsers(dest="cmd", required=True)
    for name, c in COMMANDS.items():
        sp = sub.add_parser(name, help=c["help"])
        for flag, kw in c["args"]:
            sp.add_argument(flag, **kw)
    a = p.parse_args(argv)
    if not a.json:
        return _run(a)
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        code = _run(a)
    print(json.dumps({"command": a.cmd, "exit": code, "output": buf.getvalue().splitlines()}))
    return code


def _run(a):
    try:
        return COMMANDS[a.cmd]["run"](a)
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        return 2
"""Parse and format durations like `1h30m`."""
import re

_PART = re.compile(r"(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?")


def parse_duration(s):
    """Return total seconds for a string of <digits><unit> parts (h, m, s in order)."""
    m = _PART.fullmatch(s)
    if not s or m is None:
        raise ValueError(f"invalid duration: {s!r}")
    h, mi, se = (int(g) if g else 0 for g in m.groups())
    return h * 3600 + mi * 60 + se


def format_duration(seconds):
    """Return the canonical form of a number of seconds, e.g. 5400 -> "1h30m"."""
    if seconds < 0:
        raise ValueError("duration must not be negative")
    h, rest = divmod(seconds, 3600)
    m, s = divmod(rest, 60)
    out = "".join(f"{v}{u}" for v, u in ((h, "h"), (m, "m"), (s, "s")) if v)
    return out or "0s"
import contextlib
import io
import unittest

from textkit.cli import main
from textkit.duration import format_duration, parse_duration


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class DurationTest(unittest.TestCase):
    def test_parse(self):
        for s, n in [("1h30m", 5400), ("45s", 45), ("2h5s", 7205), ("90m", 5400)]:
            self.assertEqual(parse_duration(s), n)

    def test_parse_invalid(self):
        for s in ["", "1x", "30m1h", "1h1h", "1.5h", "h", "1h 30m"]:
            with self.subTest(s=s), self.assertRaises(ValueError):
                parse_duration(s)

    def test_format(self):
        for n, s in [(5400, "1h30m"), (7205, "2h5s"), (59, "59s"), (0, "0s")]:
            self.assertEqual(format_duration(n), s)

    def test_format_negative(self):
        with self.assertRaises(ValueError):
            format_duration(-1)


class DurCommandTest(unittest.TestCase):
    def test_parse(self):
        self.assertEqual(run("dur", "1h30m"), (0, "5400\n", ""))

    def test_format(self):
        self.assertEqual(run("dur", "5400"), (0, "1h30m\n", ""))

    def test_error(self):
        code, out, err = run("dur", "30m1h")
        self.assertEqual(code, 2)
        self.assertTrue(err.startswith("error:"))

    def test_listed(self):
        self.assertIn("dur\n", run("commands")[1])
"""Each README command-table cell must equal the command's help string exactly."""
import pathlib
import re
import unittest

from textkit.cli import COMMANDS

ROOT = pathlib.Path(__file__).resolve().parent.parent


def readme_cells():
    readme = (ROOT / "README.md").read_text()
    rows = re.findall(r"^\| `([^`]+)` \| (.*?) \|$", readme, flags=re.M)
    return dict(rows)


class DocSyncTest(unittest.TestCase):
    def test_cells_match_help(self):
        cells = readme_cells()
        for name, c in COMMANDS.items():
            with self.subTest(command=name):
                self.assertIn(name, cells)
                self.assertEqual(cells[name], c["help"])

